/**
 * Génère un menu journalier cohérent, priorisé et équilibré sans jamais dépasser la cible calorique.
 *
 * Règles :
 * - Lunch/Dinner → entrée + plat + dessert si dispo
 * - Breakfast → uniquement breakfast
 * - Snacks → ajoutés uniquement si des calories restent
 * - Chaque recette = 1 portion entière (pas de fraction)
 * - Optimisation "sac à dos" pour se rapprocher au maximum de la cible sans dépasser (+1 % tolérance)
 */
export function generateMenu(recipes, userConstraints) {
  if (!Array.isArray(recipes) || !recipes.length)
    return { menu: {}, totals: { kcal: 0, protein: 0, carbs: 0, fat: 0 } };

  const {
    targetCalories = 2000,
    takenMealsObjectives = ["breakfast", "lunch", "dinner", "snacks"],
    allergies = [],
    intolerances = [],
    bannedIngredients = [],
    maxPrepTime = null,
    skillLevel = null,
    availableEquipment = [],
  } = userConstraints;

  const MAX_TOLERANCE = targetCalories * 1.01; // +1% autorisé

  // Helpers
  const normalize = (str) => String(str || "").trim().toLowerCase().replace(/s$/, "");
  const pickRandom = (arr) => arr[Math.floor(Math.random() * arr.length)];
  const getKcal = (r) => (r?.totals?.kcal ?? 0) / (r.servings && r.servings > 0 ? r.servings : 1);
  const getMacros = (r) => {
    const s = r.servings && r.servings > 0 ? r.servings : 1;
    const t = r.totals || {};
    return {
      kcal: (t.kcal ?? 0) / s,
      protein: (t.protein ?? 0) / s,
      carbs: (t.carbs ?? 0) / s,
      fat: (t.fat ?? 0) / s,
    };
  };

  // Normalisation des repas
  const normalizedMeals = takenMealsObjectives.map(normalize);

  // Filtrage des recettes selon contraintes
  const filteredRecipes = recipes.filter((r) => {
    const ingredients = (r.ingredients || []).map((i) => i.name?.toLowerCase?.() || "");
    const safe = (list, fn) => list.every((x) => fn(x));
    return (
      safe(allergies, (a) => !ingredients.includes(a.toLowerCase())) &&
      safe(intolerances, (i) => !ingredients.includes(i.toLowerCase())) &&
      safe(bannedIngredients, (b) => !ingredients.includes(b.toLowerCase())) &&
      (!maxPrepTime || (r.prepTime ?? 0) <= maxPrepTime) &&
      (!skillLevel || (r.skillLevel ?? "intermediate") === skillLevel) &&
      (!availableEquipment.length ||
        availableEquipment.every((eq) => (r.equipment || []).includes(eq)))
    );
  });

  if (!filteredRecipes.length)
    return { menu: {}, totals: { kcal: 0, protein: 0, carbs: 0, fat: 0 } };

  // Groupes par catégorie
  const byCategory = {
    starter: filteredRecipes.filter((r) => normalize(r.category) === "starter"),
    meal: filteredRecipes.filter((r) => normalize(r.category) === "meal"),
    dessert: filteredRecipes.filter((r) => normalize(r.category) === "dessert"),
    breakfast: filteredRecipes.filter((r) => normalize(r.category) === "breakfast"),
    snack: filteredRecipes.filter((r) => normalize(r.category) === "snack"),
  };

  // Construction du menu
  const menu = {};
  const used = new Set();

  const addRecipe = (cat, type) => {
    const available = byCategory[cat]?.filter((r) => !used.has(r.id)) || [];
    if (!available.length) return null;
    const chosen = pickRandom(available);
    menu[type].push(chosen);
    used.add(chosen.id);
  };

  // Lunch & Dinner (entrée + plat + dessert)
  for (const type of ["lunch", "dinner"]) {
    if (!normalizedMeals.includes(type)) continue;
    menu[type] = [];
    ["starter", "meal", "dessert"].forEach((cat) => addRecipe(cat, type));
  }

  // Breakfast
  if (normalizedMeals.includes("breakfast") && byCategory.breakfast.length) {
    menu.breakfast = [];
    addRecipe("breakfast", "breakfast");
  }

  // Calcul des totaux initiaux
  const totals = { kcal: 0, protein: 0, carbs: 0, fat: 0 };
  for (const r of Object.values(menu).flat()) {
    const t = getMacros(r);
    totals.kcal += t.kcal;
    totals.protein += t.protein;
    totals.carbs += t.carbs;
    totals.fat += t.fat;
  }

  // ⚡ Sélection des snacks via algorithme de sac à dos (0/1)
  const remainingKcal = targetCalories - totals.kcal;
  if (remainingKcal > 50 && byCategory.snack.length) {
    const snacks = byCategory.snack.filter((r) => !used.has(r.id));

    // Sac à dos dynamique (0/1) — trouve la meilleure combinaison ≤ remainingKcal
    const W = Math.floor(remainingKcal);
    const n = snacks.length;
    const dp = Array.from({ length: n + 1 }, () => Array(W + 1).fill(0));

    for (let i = 1; i <= n; i++) {
      const kcal = Math.floor(getKcal(snacks[i - 1]));
      for (let w = 0; w <= W; w++) {
        if (kcal <= w) {
          dp[i][w] = Math.max(
            dp[i - 1][w],
            dp[i - 1][w - kcal] + kcal
          );
        } else {
          dp[i][w] = dp[i - 1][w];
        }
      }
    }

    // Récupération des snacks sélectionnés
    let w = W;
    const selected = [];
    for (let i = n; i > 0; i--) {
      if (dp[i][w] !== dp[i - 1][w]) {
        selected.push(snacks[i - 1]);
        w -= Math.floor(getKcal(snacks[i - 1]));
      }
    }

    // Ajout des snacks au menu si total ≤ +1 %
    let addedKcal = 0;
    for (const s of selected.reverse()) {
      const t = getMacros(s);
      if (totals.kcal + addedKcal + t.kcal <= MAX_TOLERANCE) {
        menu.snack = menu.snack || [];
        menu.snack.push(s);
        addedKcal += t.kcal;
        totals.kcal += t.kcal;
        totals.protein += t.protein;
        totals.carbs += t.carbs;
        totals.fat += t.fat;
        used.add(s.id);
      }
    }
  }

  // Clamp final : ne dépasse jamais la tolérance de +1 %
  if (totals.kcal > MAX_TOLERANCE) {
    totals.kcal = MAX_TOLERANCE;
  }

  return { menu, totals };
}
