<template>
  <loading-element v-if="isLoadingRecipes" />

  <div class="main bg-primary" v-else>
    <TopDeck
      v-if="authStore.userInfos"
      firstElement="Mes"
      secondElement="menus"
      :coloredSecond="true"
    />

    <div class="recapBanner pa-4 rounded-lg bg-white mt-4">
      <h3 class="mb-2">Récapitulatif des contraintes de mes menus</h3>

      <p><strong>Objectif :</strong> {{ $t(weightObjective) }}</p>
      <p><strong>Calories cibles :</strong> {{ targetCalories.toFixed(0) }} kcal / jour</p>

      <div class="macros mt-3">
        <p><strong>Protéines :</strong> {{ proteinNeeds.toFixed(0) }} g</p>
        <p><strong>Lipides :</strong> {{ fatNeeds.toFixed(0) }} g</p>
        <p><strong>Glucides :</strong> {{ carbNeeds.toFixed(0) }} g</p>
      </div>

      <div class="cookingData mt-3">
        <p><strong>Temps de préparation moyen :</strong> {{ $t(userConstraints.averageCookingTime) }}</p>
        <p><strong>Niveau en cuisine :</strong> {{ $t(userConstraints.cookingSkills) }}</p>
        <p><strong>Régime alimentaire :</strong> {{ userConstraints.diet.length ? userConstraints.diet.map(d => $t(d)).join(", ") : "Aucun" }}</p>
        <p><strong>Équipement disponible :</strong> {{ userConstraints.equipement.length ? userConstraints.equipement.map(e => $t(e)).join(", ") : "Aucun" }}</p>
        <p><strong>Intolérances alimentaires :</strong> {{ userConstraints.intolerances.length ? userConstraints.intolerances.map(i => $t(i)).join(", ") : "Aucune" }}</p>
        <p><strong>Repas déjà pris dans la journée :</strong> {{ userConstraints.takenMealsObjectives.length ? userConstraints.takenMealsObjectives.map(m => $t(m)).join(", ") : "Aucun" }}</p>
      </div>
    </div>

    <!-- MENU GÉNÉRÉ -->
    <div v-if="menuData.menu && Object.keys(menuData.menu).length" class="mt-6 bg-white pa-4 rounded-lg">
      <h3 class="mb-4">Menu généré</h3>

      <div
        v-for="(meals, mealName) in menuData.menu"
        :key="mealName"
        class="menuSection mb-6"
      >
        <h4 class="menuTitle mb-2 text-capitalize">
          {{ $t(mealName) }}
        </h4>

        <div v-if="meals.length" class="d-flex flex-column gap-2">
          <v-card
            v-for="(recipe, index) in meals"
            :key="recipe.id || index"
            class="pa-3 ma-1"
            outlined
          >
            <div class="d-flex justify-space-between align-center">
              <div>
                <p class="mb-1 font-weight-medium">{{ recipe.title || 'Sans titre' }}</p>
                <p class="text-caption mb-0">
                  {{ $t(recipe.category) }} — {{ (recipe.totals?.kcal ?? 0).toFixed(0) / recipe.servings }} kcal
                </p>
              </div>

              <v-btn
                size="small"
                variant="text"
                color="primary"
                @click="router.push({ name: 'recipe_detail', params: { id: recipe.id } })"
              >
                Voir
              </v-btn>
            </div>
          </v-card>
        </div>

        <p v-else class="text-caption text-grey">
          Aucune recette disponible pour ce repas.
        </p>
      </div>

      <div v-if="menuData.menu && Object.keys(menuData.menu).length" class="mt-6 bg-white pa-4 rounded-lg">
        <h3 class="mb-4">Totaux nutritionnels du menu</h3>
        <p><strong>Calories totales :</strong> {{ menuData.totals.kcal.toFixed(0) }} kcal</p>
        <p><strong>Protéines totales :</strong> {{ menuData.totals.protein.toFixed(0) }} g</p>
        <p><strong>Lipides totales :</strong> {{ menuData.totals.fat.toFixed(0) }} g</p>
        <p><strong>Glucides totales :</strong> {{ menuData.totals.carbs.toFixed(0) }} g</p>
      </div>
    </div>

  </div>

  <v-snackbar v-if="errorMessage" v-model="errorMessage" color="error" top right>
    {{ errorMessage }}
  </v-snackbar>
</template>

<script>
import { computed, ref, onMounted, watch } from "vue";
import LoadingElement from "../Animations/LoadingElement.vue";
import TopDeck from "../Utils/TopDeck.vue";
import { useAuthStore } from "@/store/auth_store";
import {
  getBaseMetabolicRate,
  getDailyNeeds,
  getTargetCalories,
  calculateMacros,
} from "@/service/health_service";
import {
  getUserRecipes
} from "@/service/recipe_service";
import {
  generateMenu
} from "@/service/menu_service";

export default {
  name: "MenuPage",
  components: { LoadingElement, TopDeck },
  setup() {
    const authStore = useAuthStore();
    const errorMessage = ref("");
    const recipes = ref([]);
    const isLoadingRecipes = ref(false);


    onMounted(() => {
      watch(
        () => authStore.userInfos,
        async (newUserInfos) => {
          if (!newUserInfos?.userid) return;
          try {
            isLoadingRecipes.value = true;
            const data = await getUserRecipes(newUserInfos.userid);
            recipes.value = Object.entries(data).map(([id, value]) => ({ id, ...value }));
          } catch (error) {
            errorMessage.value = "Erreur lors du chargement des recettes utilisateur.";
            console.error(error);
          } finally {
            isLoadingRecipes.value = false;
          }
        },
        { immediate: true }
      );
    });

    // Données du store
    const weight = authStore.userInfos?.actualWeight || 70;
    const height = authStore.userInfos?.actualSize || 175;
    const age = authStore.userInfos?.age || 30;
    const sex = authStore.userInfos?.sex || "male";
    const activityLevel = authStore.userInfos?.activityLevel || "sedentary";
    const weightObjective = authStore.userInfos?.weightObjective || "maintainWeight";

    //Cooking data
    const userConstraints = computed(() => ({
      targetCalories: targetCalories.value,
      takenMealsObjectives: authStore.userInfos?.takenMealsObjectives || ["breakfast", "lunch", "dinner"],
      allergies: authStore.userInfos?.allergies || [],
      intolerances: authStore.userInfos?.intolerances || [],
      diet: authStore.userInfos?.diet || [],
      bannedIngredients: authStore.userInfos?.bannedIngredients || [],
      averageCookingTime: authStore.userInfos?.averageCookingTime || "15To30Minutes",
      cookingSkills: authStore.userInfos?.cookingSkills || null,
      equipement: authStore.userInfos?.equipement || [],
    }));

    const menuData = computed(() => generateMenu(recipes.value, userConstraints.value));

    // Calculs nutritionnels
    const tmb = computed(() => getBaseMetabolicRate(age, height, weight, sex));
    const dailyNeeds = computed(() => getDailyNeeds(tmb.value, activityLevel));
    const targetCalories = computed(() => getTargetCalories(dailyNeeds.value, weightObjective));

    const macros = computed(() =>
      calculateMacros(weight, activityLevel, weightObjective, targetCalories.value)
    );

    const proteinNeeds = computed(() => macros.value.proteinNeeds);
    const fatNeeds = computed(() => macros.value.fatNeeds);
    const carbNeeds = computed(() => macros.value.carbNeeds);

    return {
      //User data
      authStore,
      errorMessage,
      recipes,
      isLoadingRecipes, 
      weightObjective,
      targetCalories,
      proteinNeeds,
      fatNeeds,
      carbNeeds,
      //Cooking data,
      userConstraints,
      menuData,
    };
  },
};
</script>

<style scoped>
  .recapBanner {
    background: #fff;
    border-radius: 12px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
  }

  .macros p {
    margin: 4px 0;
  }

  .menuSection {
    border-bottom: 1px solid #eee;
    padding-bottom: 1rem;
  }

  .menuTitle {
    font-weight: 600;
    font-size: 1.2rem;
    color: rgb(var(--v-theme-accent));
  }

  .menuSection:last-child {
    border-bottom: none;
  }
</style>
