<template>
    <LoadingElement v-if="authStore.isLoading" />
    <div class="main bg-primary" v-else>
        <div class="rowSpaceBetween fullWidth">
            <TopDeck firstElement="Bonjour" :secondElement="authStore.userInfos?.username" coloredSecond="true"></TopDeck>
            <div class="noSpaceRowAction">
                <div class="flex-end mr-3">
                    <v-select
                        v-model="isDarkTheme"
                        :items="[
                            { text: 'Clair', value: false },
                            { text: 'Sombre', value: true }
                        ]"
                        item-title="text"
                        item-value="value"
                        label="Thème"
                        variant="outlined"
                        density="compact"
                        rounded="xl"
                        hide-details="true"
                        style="max-width: 200px; margin: 0 auto;"
                        @update:modelValue="toggleTheme($event)"
                    />
                </div>
                <v-btn v-if="authStore.isSignedIn" @click="handleSignout" color="error" rounded="xl" class="white-text-button">
                    <v-icon icon="mdi-power" class="mr-2"></v-icon>
                    Déconnexion
                </v-btn>
            </div>
        </div>
        <div class="myBasicInfosContainer">
            <div class="basicInfosHeader">
                <h2>Mes informations de base</h2>
                <v-btn color="accent" class="white-text-button" rounded="xl" size="small">
                    <v-icon icon="mdi-pencil" class="mr-2"></v-icon>
                    Modifier
                </v-btn>
            </div>
            <p><strong>Nom :</strong> {{ authStore.userInfos?.username }}</p>
            <p><strong>Email :</strong> {{ authStore.userInfos?.email }}</p>
            <v-btn color="orange" class="white-text-button" rounded="xl" size="small" @click="changePassword">
                <v-icon icon="mdi-pencil" class="mr-2"></v-icon>
                Changer mon mot de passe
            </v-btn>
        </div>
        <HealthStatsBloc />
        <Info_display_bloc :user="authStore.userInfos" />
    </div>  

    <v-snackbar v-model="showSnack" :color="snackColor" :timeout="2000" location="bottom">
        {{ snackMessage }}
    </v-snackbar>

    <!-- 🔹 Modal de changement de mot de passe -->
    <v-dialog v-model="showPasswordDialog" max-width="400">
        <v-card class="p-4 rounded-2xl">
        <v-card-title class="text-lg font-bold">
            Changer mon mot de passe
        </v-card-title>
        <v-card-text>
            <form @submit.prevent="onSubmit" class="stack">
            <v-text-field
                v-model="email"
                type="email"
                label="Votre e-mail"
                variant="outlined"
                density="compact"
                required
            />
            <v-btn :loading="loading" type="submit" color="primary" rounded="xl" block>
                <v-icon icon="mdi-email" class="mr-2" />
                {{ loading ? 'Envoi…' : 'Envoyer le lien' }}
            </v-btn>
            <p v-if="done" class="hint">
                Si un compte existe pour cet e-mail, un message vient d’être envoyé.
            </p>
            <p v-if="error" class="error">{{ error }}</p>
            </form>
        </v-card-text>
        <v-card-actions class="justify-end">
            <v-btn text @click="showPasswordDialog = false">Fermer</v-btn>
        </v-card-actions>
        </v-card>
    </v-dialog>
</template>

<script>
    import { ref, onMounted } from "vue";
    import { getAuth, signOut } from "firebase/auth";
    import { useRouter } from "vue-router";
    import TopDeck from '../Utils/TopDeck.vue';
    import { useTheme } from 'vuetify';
    import LoadingElement from "../Animations/LoadingElement.vue";
    import { useAuthStore } from '@/store/auth_store'
    import Info_display_bloc from "./InfoDisplayBlock.vue";
    import { requestPasswordReset } from '@/service/auth_service';
    import HealthStatsBloc from "./HealthStatsBloc.vue";

    export default {
        name: 'ProfilPage',
        components: { LoadingElement, TopDeck, Info_display_bloc, HealthStatsBloc },
        setup() {
            const router = useRouter();
            const auth = getAuth();
            const authStore = useAuthStore();
            const theme = useTheme();
            const isDarkTheme = ref(false);
            const showSnack = ref(false);
            const snackMessage = ref('');
            const snackColor = ref('success');

            const showPasswordDialog = ref(false);
            const email = ref('');
            const loading = ref(false);
            const done = ref(false);
            const error = ref('');

            const toggleTheme = (value) => {
                theme.global.name.value = value ? 'dark' : 'light';
                localStorage.setItem('theme', value ? 'dark' : 'light');
            };

            const changePassword = () => {
                showPasswordDialog.value = true;
            };

            async function onSubmit() {
                loading.value = true;
                error.value = '';
                try {
                    await requestPasswordReset(email.value);
                    done.value = true; // message générique
                } catch (e) {
                    console.error('requestPasswordReset error', e);
                    done.value = true;
                } finally {
                    loading.value = false;
                }
            }

            onMounted(() => {
                const savedTheme = localStorage.getItem('theme');
                if (savedTheme) {
                    isDarkTheme.value = savedTheme === 'dark';
                    theme.global.name.value = isDarkTheme.value ? 'dark' : 'light';
                }
            });

            const handleSignout = () => {
                signOut(auth)
                    .then(() => {
                        router.push('/login');
                    })
                    .catch((error) => {
                        console.error(error);
                    });
            };

            return {
                authStore,
                isDarkTheme,
                showSnack,
                snackMessage,
                snackColor,
                showPasswordDialog,
                email,
                loading,
                done,
                error,
                onSubmit,
                toggleTheme,
                handleSignout,
                changePassword,
            };
        },
    }
</script>

